package pe.vichaval.gestionriego.riego.dto;import jakarta.validation.constraints.*;import java.time.*;public class TurnoForm{@NotNull private Long parcelaId;@NotNull private LocalDate fecha;@NotNull private LocalTime horaInicio;@NotNull@Min(30)private Integer duracionMinutos=60;private String observaciones;public Long getParcelaId(){return parcelaId;}public void setParcelaId(Long x){parcelaId=x;}public LocalDate getFecha(){return fecha;}public void setFecha(LocalDate x){fecha=x;}public LocalTime getHoraInicio(){return horaInicio;}public void setHoraInicio(LocalTime x){horaInicio=x;}public Integer getDuracionMinutos(){return duracionMinutos;}public void setDuracionMinutos(Integer x){duracionMinutos=x;}public String getObservaciones(){return observaciones;}public void setObservaciones(String x){observaciones=x;}}